    pricing: [{ item: 'Работы по озеленению помещений — стартовый ориентир', value: 'от 690 ₽/м²', note: 'Растения, кашпо, грунт, доставка и состав композиции рассчитываются отдельно; цену уточняем по фото или осмотру.' }],
