function slugify(value: string) {
  return value.toLowerCase().replace(/[^a-z0-9а-яё]+/gi, '-').replace(/^-+|-+$/g, '');
}

function journalSlugify(value: string) {
  const translit: Record<string, string> = {
    а: 'a', б: 'b', в: 'v', г: 'g', д: 'd', е: 'e', ё: 'e', ж: 'zh', з: 'z', и: 'i', й: 'y',
    к: 'k', л: 'l', м: 'm', н: 'n', о: 'o', п: 'p', р: 'r', с: 's', т: 't', у: 'u', ф: 'f',
    х: 'h', ц: 'ts', ч: 'ch', ш: 'sh', щ: 'sch', ъ: '', ы: 'y', ь: '', э: 'e', ю: 'yu', я: 'ya'
  };
  return value.toLowerCase().split('').map((letter) => translit[letter] ?? letter).join('').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

function getProjectPath(project: HouseProject) {
  const titleSlug = journalSlugify(project.title) || project.id;
  const semanticSlug = project.category === 'bath'
    ? (/^ban/.test(titleSlug) ? titleSlug : `proekt-bani-${titleSlug}`)
    : (/(^|-)dom(-|$)|(^|-)doma(-|$)|(^|-)house(-|$)/.test(titleSlug) ? titleSlug : `proekt-doma-${titleSlug}`);
  return `/project/${project.slug || semanticSlug}`;
}

function writePageSEO({ title, description, path, image, schema }: { title: string; description: string; path: string; image?: string; schema?: unknown }) {
  document.title = title;
  const setMeta = (key: string, content: string, property = false) => {
    const selector = property ? `meta[property="${key}"]` : `meta[name="${key}"]`;
    let element = document.head.querySelector(selector) as HTMLMetaElement | null;
    if (!element) {
      element = document.createElement('meta');
      if (property) element.setAttribute('property', key);
      else element.name = key;
      document.head.appendChild(element);
    }
    element.content = content;
  };
  setMeta('description', description);
  setMeta('og:title', title, true);
  setMeta('og:description', description, true);
  setMeta('og:type', 'website', true);
  setMeta('og:url', `${window.location.origin}${path}`, true);
  if (image) setMeta('og:image', image.startsWith('http') ? image : `${window.location.origin}${image}`, true);
  let canonical = document.head.querySelector('link[rel="canonical"]') as HTMLLinkElement | null;
  if (!canonical) { canonical = document.createElement('link'); canonical.rel = 'canonical'; document.head.appendChild(canonical); }
  canonical.href = `${window.location.origin}${path}`;
  document.getElementById('page-jsonld')?.remove();
  if (schema) {
    const script = document.createElement('script');
    script.id = 'page-jsonld';
    script.type = 'application/ld+json';
    script.textContent = JSON.stringify(schema);
    document.head.appendChild(script);
  }
}

function normalizePathname(pathname: string) {
  try {
    return decodeURIComponent(pathname);
  } catch {
    return pathname;
  }
}

