function DualRangeSlider({
  min,
  max,
  step = 1,
  valueMin,
  valueMax,
  onChangeMin,
  onChangeMax,
  disabled
}: {
  min: number;
  max: number;
  step?: number;
  valueMin: number;
  valueMax: number;
  onChangeMin: (value: number) => void;
  onChangeMax: (value: number) => void;
  disabled?: boolean;
}) {
  const safeMin = Math.min(valueMin, valueMax);
  const safeMax = Math.max(valueMin, valueMax);
  const range = Math.max(max - min, 1);
  const leftPercent = ((safeMin - min) / range) * 100;
  const rightPercent = ((safeMax - min) / range) * 100;

  return (
    <div className={`double-range ${disabled ? 'disabled' : ''}`}>
      <div className="double-range-track" />
      <div className="double-range-fill" style={{ left: `${leftPercent}%`, width: `${Math.max(rightPercent - leftPercent, 0)}%` }} />
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={safeMin}
        onChange={(e) => onChangeMin(Number(e.target.value))}
        disabled={disabled}
        className="double-range-input"
      />
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={safeMax}
        onChange={(e) => onChangeMax(Number(e.target.value))}
        disabled={disabled}
        className="double-range-input"
      />
    </div>
  );
}

function CatalogPage({ category, sectionTitle }: { category: 'house' | 'bath'; sectionTitle: string }) {
  const params = new URLSearchParams(window.location.search);
  const type = params.get('type') || 'Все типы';
  const [projects, setProjects] = useState<HouseProject[]>([]);
  const [selectedFloors, setSelectedFloors] = useState<string[]>([]);
  const [selectedStyles, setSelectedStyles] = useState<string[]>([]);
  const [minArea, setMinArea] = useState<number | null>(null);
  const [maxArea, setMaxArea] = useState<number | null>(null);
  const [minRooms, setMinRooms] = useState<number | null>(null);
  const [maxRooms, setMaxRooms] = useState<number | null>(null);
  const [minPrice, setMinPrice] = useState<number | null>(null);
  const [maxPrice, setMaxPrice] = useState<number | null>(null);
  const [requestProject, setRequestProject] = useState<HouseProject | null>(null);

  useEffect(() => {
    document.title = category === 'bath'
      ? 'Проекты бань в Пензе — планировки и ориентир цен | Evtenia'
      : 'Проекты домов в Пензе — каталог и цены | Evtenia';
    fetch(`${API_BASE}/api/projects`)
      .then((res) => (res.ok ? res.json() : Promise.reject(new Error('no api'))))
      .then((data: HouseProject[]) => setProjects(Array.isArray(data) && data.length ? data : FALLBACK_PROJECTS))
      .catch(() => setProjects(FALLBACK_PROJECTS));
  }, [sectionTitle]);

  const normalizeCategory = (item: HouseProject): 'house' | 'bath' => {
    const rawCategory = String(item.category || '').trim().toLowerCase();
    if (
      rawCategory === 'bath' ||
      rawCategory === 'baths' ||
      rawCategory === 'баня' ||
      rawCategory === 'бани' ||
      rawCategory.includes('бан') ||
      rawCategory.includes('саун')
    ) {
      return 'bath';
    }
    if (
      rawCategory === 'house' ||
      rawCategory === 'home' ||
      rawCategory === 'дом' ||
      rawCategory === 'дома' ||
      rawCategory.includes('дом')
    ) {
      return 'house';
    }
    const titleHint = `${item.title} ${item.shortDescription} ${item.fullDescription}`.toLowerCase();
    if (titleHint.includes('бан') || titleHint.includes('саун')) return 'bath';
    return 'house';
  };

  const isBathCatalog = category === 'bath';
  const byCategory = projects.filter((item) => normalizeCategory(item) === (isBathCatalog ? 'bath' : 'house'));
  const categoryScopedProjects = byCategory;
  const floorOptions = Array.from(new Set(categoryScopedProjects.map((item) => item.floors))).filter(Boolean);
  const typeOptions = Array.from(new Set(categoryScopedProjects.map((item) => item.constructionType))).filter(Boolean);
  const effectiveType = typeOptions.includes(type) || type === 'Все типы' ? type : 'Все типы';
  const styleOptions = Array.from(new Set(categoryScopedProjects.map((item) => (item.style || '').trim()).filter(Boolean)));
  const styleOptionsKey = styleOptions.join('\u0000');
  const parseNum = (value: unknown) => {
    const digits = String(value ?? '').match(/\d+/);
    const parsed = Number(digits?.[0] || '0');
    return Number.isFinite(parsed) ? parsed : 0;
  };
  const parsePrice = (value: unknown) => {
    const parsed = Number(String(value ?? '').replace(/[^\d]/g, '') || '0');
    return Number.isFinite(parsed) ? parsed : 0;
  };
  const areaValues = categoryScopedProjects.map((item) => parseNum(item.area)).filter((value) => value > 0);
  const roomValues = categoryScopedProjects.map((item) => parseNum(item.bedrooms)).filter((value) => value > 0);
  const priceValues = categoryScopedProjects.map((item) => parsePrice(item.priceFrom)).filter((value) => value > 0);
  const minAreaLimit = areaValues.length ? Math.min(...areaValues) : 0;
  const maxAreaLimit = areaValues.length ? Math.max(...areaValues) : 0;
  const minRoomsLimit = roomValues.length ? Math.min(...roomValues) : 0;
  const maxRoomsLimit = roomValues.length ? Math.max(...roomValues) : 0;
  const minPriceLimit = priceValues.length ? Math.min(...priceValues) : 0;
  const maxPriceLimit = priceValues.length ? Math.max(...priceValues) : 0;

  useEffect(() => {
    setSelectedStyles((prev) => {
      const next = prev.filter((style) => styleOptions.includes(style));
      return next.length === prev.length ? prev : next;
    });
  }, [styleOptionsKey]);
  useEffect(() => {
    setMinArea(minAreaLimit);
    setMaxArea(maxAreaLimit);
    setMinRooms(minRoomsLimit);
    setMaxRooms(maxRoomsLimit);
    setMinPrice(minPriceLimit);
    setMaxPrice(maxPriceLimit);
  }, [minAreaLimit, maxAreaLimit, minRoomsLimit, maxRoomsLimit, minPriceLimit, maxPriceLimit]);

  const byTypeProjects = categoryScopedProjects.filter((item) => effectiveType === 'Все типы' || item.constructionType === effectiveType);
  const filteredStrict = byTypeProjects.filter((item) => {
    const byFloor = !selectedFloors.length || selectedFloors.includes(item.floors);
    const areaValue = parseNum(item.area);
    const roomsValue = parseNum(item.bedrooms);
    const priceValue = parsePrice(item.priceFrom);
    const areaMin = minArea ?? minAreaLimit;
    const areaMax = maxArea ?? maxAreaLimit;
    const roomsMin = minRooms ?? minRoomsLimit;
    const roomsMax = maxRooms ?? maxRoomsLimit;
    const priceMin = minPrice ?? minPriceLimit;
    const priceMax = maxPrice ?? maxPriceLimit;
    const byArea = !maxAreaLimit || areaValue === 0 || (areaValue >= areaMin && areaValue <= areaMax);
    const byRooms = !maxRoomsLimit || roomsValue === 0 || (roomsValue >= roomsMin && roomsValue <= roomsMax);
    const byPrice = !maxPriceLimit || priceValue === 0 || (priceValue >= priceMin && priceValue <= priceMax);
    const byStyle = !selectedStyles.length || selectedStyles.includes(item.style || '');
    return byFloor && byStyle && byArea && byRooms && byPrice;
  });
  const filteredProjects = filteredStrict;

  return (
    <div>
      <InternalHeader />
      <section className="internal-body">
        <div className="container">
          <Breadcrumbs items={["Главная", sectionTitle, effectiveType]} />
          <h1>{isBathCatalog ? 'Проекты бань в Пензе' : sectionTitle}</h1>
          {isBathCatalog ? <div className="bath-catalog-intro">
            <p>Типовые идеи бань для дачи и загородного участка в Пензе и Пензенской области: от компактных каркасных решений до просторных деревянных банных домов.</p>
            <p>Карточки помогают выбрать площадь и состав помещений. Изображения — иллюстрации вариантов, а не фотографии построенных объектов. Цены указаны ориентировочно «от»; точный расчёт зависит от основания, печи и дымохода, отделки, инженерии, доставки и особенностей участка.</p>
            <a href="tel:+79022090179">Обсудить баню с менеджером <span aria-hidden="true">→</span></a>
          </div> : null}
          <div className="catalog-layout">
            <aside className="catalog-filters">
              <div className="filter-block">
                <h4>Этажность</h4>
                {floorOptions.map((floor) => (
                  <label key={floor}><input type="checkbox" checked={selectedFloors.includes(floor)} onChange={(e) => setSelectedFloors(e.target.checked ? [...selectedFloors, floor] : selectedFloors.filter((f) => f !== floor))} /> {floor}</label>
                ))}
              </div>
              {styleOptions.length ? (
                <div className="filter-block filter-block-style">
                  <h4>Стиль</h4>
                  <div className="style-grid">
                    {styleOptions.map((style) => (
                      <label key={style}>
                        <input
                          type="checkbox"
                          checked={selectedStyles.includes(style)}
                          onChange={(e) => setSelectedStyles(e.target.checked ? [...selectedStyles, style] : selectedStyles.filter((s) => s !== style))}
                        />
                        {' '}{style === 'Скандинавский' ? 'Сканди' : style}
                      </label>
                    ))}
                  </div>
                </div>
              ) : null}
              <div className="filter-block">
                <h4>Площадь: {(minArea ?? minAreaLimit)} — {(maxArea ?? maxAreaLimit)} м²</h4>
                <DualRangeSlider
                  min={minAreaLimit || 0}
                  max={maxAreaLimit || 0}
                  valueMin={minArea ?? minAreaLimit}
                  valueMax={maxArea ?? maxAreaLimit}
                  onChangeMin={(value) => setMinArea(Math.min(value, maxArea ?? maxAreaLimit))}
                  onChangeMax={(value) => setMaxArea(Math.max(value, minArea ?? minAreaLimit))}
                  disabled={!maxAreaLimit}
                />
              </div>
              {!isBathCatalog ? <div className="filter-block">
                <h4>Комнаты: {(minRooms ?? minRoomsLimit)} — {(maxRooms ?? maxRoomsLimit)}</h4>
                <DualRangeSlider
                  min={minRoomsLimit || 0}
                  max={maxRoomsLimit || 0}
                  valueMin={minRooms ?? minRoomsLimit}
                  valueMax={maxRooms ?? maxRoomsLimit}
                  onChangeMin={(value) => setMinRooms(Math.min(value, maxRooms ?? maxRoomsLimit))}
                  onChangeMax={(value) => setMaxRooms(Math.max(value, minRooms ?? minRoomsLimit))}
                  disabled={!maxRoomsLimit}
                />
              </div> : null}
              <div className="filter-block">
                <h4>Цена: {(minPrice ?? minPriceLimit).toLocaleString('ru-RU')} — {(maxPrice ?? maxPriceLimit).toLocaleString('ru-RU')} ₽</h4>
                <DualRangeSlider
                  min={minPriceLimit || 0}
                  max={maxPriceLimit || 0}
                  step={100000}
                  valueMin={minPrice ?? minPriceLimit}
                  valueMax={maxPrice ?? maxPriceLimit}
                  onChangeMin={(value) => setMinPrice(Math.min(value, maxPrice ?? maxPriceLimit))}
                  onChangeMax={(value) => setMaxPrice(Math.max(value, minPrice ?? minPriceLimit))}
                  disabled={!maxPriceLimit}
                />
              </div>
            </aside>

            <div>
              <div className="type-chips">
                <button className={effectiveType === 'Все типы' ? 'active' : ''} onClick={() => { window.location.href = `${window.location.pathname}?type=${encodeURIComponent('Все типы')}`; }}>Все типы</button>
                {typeOptions.map((option) => (
                  <button key={option} className={effectiveType === option ? 'active' : ''} onClick={() => { window.location.href = `${window.location.pathname}?type=${encodeURIComponent(option)}`; }}>{option}</button>
                ))}
              </div>
              <div className="catalog-grid">
                {filteredProjects.map((project) => <ProjectTile project={project} key={project.id} onRequest={setRequestProject} />)}
              </div>
              {!filteredProjects.length ? <div className="bath-catalog-empty"><h2>Подходящих вариантов пока нет</h2><p>Расскажите, какая площадь и планировка вам нужны — подготовим индивидуальный ориентир.</p><a href="tel:+79022090179">Позвонить в Evtenia</a></div> : null}
            </div>
          </div>
          {isBathCatalog ? <section className="bath-catalog-guide" aria-labelledby="bath-catalog-guide-title">
            <div className="bath-catalog-guide-heading">
              <span>Строительство бань в Пензе и области</span>
              <h2 id="bath-catalog-guide-title">Подберём баню под участок, привычки и бюджет</h2>
              <p>Представленные проекты — типовые идеи для первого выбора. Мы уточним, сколько человек будет пользоваться баней, нужна ли отдельная комната отдыха, планируется ли зимняя эксплуатация и какие ограничения есть на участке.</p>
            </div>
            <div className="bath-catalog-guide-grid">
              <article><h3>Небольшая дачная баня</h3><p>Площадь 12–16 м²: компактные парная и моечная, предбанник или небольшая зона отдыха. Подходит, когда важны простая планировка и небольшой занимаемый участок.</p></article>
              <article><h3>Баня для семьи и гостей</h3><p>Площадь 20–24 м²: к парной и моечной добавляется отдельная комната отдыха, а при необходимости — терраса или веранда. Вариант для более длительных встреч.</p></article>
              <article><h3>Банный дом</h3><p>Площадь от 36 м²: можно предусмотреть просторную комнату отдыха и гостевую зону. Для круглогодичного использования отдельно рассчитываются отопление, вентиляция и водоотведение.</p></article>
            </div>
            <div className="bath-catalog-guide-details">
              <div><h3>Что влияет на стоимость</h3><p>В стартовый ориентир может входить только базовая комплектация строения. На окончательную цену влияют материал и сечение стен, утепление, основание, кровля, отделка парной, печь и дымоход, доставка, монтаж и подключение инженерных систем. Поэтому в карточках стоят цены «от», а для сложных вариантов — «по запросу».</p></div>
              <div><h3>Как проходит расчёт</h3><ol><li>Уточняем размеры, сценарий использования и пожелания к помещениям.</li><li>Проверяем участок, подъезд и возможность подвести коммуникации.</li><li>Согласуем материал, комплектацию и состав работ.</li><li>Готовим предварительную смету и сроки; финальные условия фиксируем до начала работ.</li></ol></div>
            </div>
            <div className="bath-catalog-faq">
              <h3>Частые вопросы</h3>
              <details><summary>Это готовые проекты с утверждённой сметой?</summary><p>Нет. Это типовые концепции для подбора площади, материалов и состава помещений. Рабочее решение, основание и смета уточняются после проверки участка и комплектации.</p></details>
              <details><summary>Что означает цена «от»?</summary><p>Это ориентировочная начальная стоимость базового варианта. Печь, дымоход, фундамент, доставка и дополнительные инженерные работы могут считаться отдельно — точный состав указываем в расчёте.</p></details>
              <details><summary>Вы строите только в Пензе?</summary><p>Рассматриваем заявки по Пензе и Пензенской области. Возможность и стоимость доставки за пределы города зависят от адреса, подъездной дороги и выбранной технологии.</p></details>
            </div>
            <div className="bath-catalog-guide-cta"><div><strong>Нужен свой размер или планировка?</strong><span>Опишите задачу — подготовим ориентир по комплектации, срокам и стоимости.</span></div><button type="button" disabled={!categoryScopedProjects.length} onClick={() => categoryScopedProjects[0] && setRequestProject(categoryScopedProjects[0])}>Получить расчёт бани <span aria-hidden="true">→</span></button></div>
          </section> : null}
        </div>
      </section>
      <SiteFooter />
      <PromoLeadModal
        open={Boolean(requestProject)}
        onClose={() => setRequestProject(null)}
        title={requestProject ? `Заявка: ${requestProject.title}` : 'Заявка'}
        promoText={isBathCatalog ? 'Получите ориентировочный расчёт бани' : '🎁 Проект дома в подарок'}
        messagePrefix={requestProject ? `Заявка на расчёт ${requestProject.category === 'bath' ? 'бани' : 'дома'}: ${requestProject.title}` : ''}
        sourceTitle={requestProject ? `Проект ${requestProject.category === 'bath' ? 'бани' : 'дома'}: ${requestProject.title}` : `Заявка на расчёт ${isBathCatalog ? 'бани' : 'дома'}`}
      />
    </div>
  );
}

